  1	import java.util.ArrayList;
  2	import java.util.Comparator;
  3	import java.util.Objects;
  4	import java.util.PriorityQueue;
  5	import java.util.function.BiConsumer;
  6	
  7	class HuffmanCoding {
  8	
  9	    private static final int INTERNAL_NODE_SYMBOL_INDEX = -1;
 10	    private static final char LEFT_BRANCH_CODE = '0';
 11	    private static final char RIGHT_BRANCH_CODE = '1';
 12	    private static final String SINGLE_SYMBOL_CODE = String.valueOf(LEFT_BRANCH_CODE);
 13	
 14	    private static final Comparator<Node> NODE_ORDER = Comparator
 15	            .comparingLong((Node node) -> node.frequency)
 16	            .thenComparingInt(node -> node.tieBreakIndex);
 17	
 18	    private HuffmanCoding() {
 19	    }
 20	
 21	    static ArrayList<String> huffmanCodes(String symbols, int[] frequencies) {
 22	        return HuffmanTree.build(symbols, frequencies).codesInTraversalOrder();
 23	    }
 24	
 25	    static ArrayList<String> huffmanCodesBySymbol(String symbols, int[] frequencies) {
 26	        return HuffmanTree.build(symbols, frequencies).codesBySymbolOrder();
 27	    }
 28	
 29	    public static void main(String[] args) {
 30	        String s = "abcdef";
 31	        int[] freq = {5, 9, 12, 13, 16, 45};
 32	        ArrayList<String> codes = huffmanCodes(s, freq);
 33	
 34	        for (String code : codes) {
 35	            System.out.print(code + " ");
 36	        }
 37	    }
 38	
 39	    private static final class Node {
 40	        private final long frequency;
 41	        private final int tieBreakIndex;
 42	        private final int symbolIndex;
 43	        private final Node left;
 44	        private final Node right;
 45	
 46	        private Node(int frequency, int symbolIndex) {
 47	            this.frequency = frequency;
 48	            this.tieBreakIndex = symbolIndex;
 49	            this.symbolIndex = symbolIndex;
 50	            this.left = null;
 51	            this.right = null;
 52	        }
 53	
 54	        private Node(Node left, Node right) {
 55	            this.frequency = left.frequency + right.frequency;
 56	            this.tieBreakIndex = Math.min(left.tieBreakIndex, right.tieBreakIndex);
 57	            this.symbolIndex = INTERNAL_NODE_SYMBOL_INDEX;
 58	            this.left = left;
 59	            this.right = right;
 60	        }
 61	
 62	        private boolean isLeaf() {
 63	            return left == null && right == null;
 64	        }
 65	    }
 66	
 67	    private static final class HuffmanTree {
 68	        private final Node root;
 69	        private final int symbolCount;
 70	
 71	        private HuffmanTree(Node root, int symbolCount) {
 72	            this.root = root;
 73	            this.symbolCount = symbolCount;
 74	        }
 75	
 76	        private static HuffmanTree build(String symbols, int[] frequencies) {
 77	            validateInput(symbols, frequencies);
 78	            Node root = symbols.isEmpty() ? null : buildTree(frequencies);
 79	            return new HuffmanTree(root, symbols.length());
 80	        }
 81	
 82	        private ArrayList<String> codesInTraversalOrder() {
 83	            ArrayList<String> codes = new ArrayList<>(symbolCount);
 84	            collectLeafCodes(root, new StringBuilder(), (leaf, code) -> codes.add(code));
 85	            return codes;
 86	        }
 87	
 88	        private ArrayList<String> codesBySymbolOrder() {
 89	            ArrayList<String> codes = createEmptyCodeList(symbolCount);
 90	            collectLeafCodes(root, new StringBuilder(), (leaf, code) -> codes.set(leaf.symbolIndex, code));
 91	            return codes;
 92	        }
 93	
 94	        private static Node buildTree(int[] frequencies) {
 95	            PriorityQueue<Node> nodes = createLeafQueue(frequencies);
 96	
 97	            while (nodes.size() > 1) {
 98	                nodes.add(mergeLowestFrequencyNodes(nodes));
 99	            }
100	
101	            return nodes.poll();
102	        }
103	
104	        private static PriorityQueue<Node> createLeafQueue(int[] frequencies) {
105	            PriorityQueue<Node> nodes = new PriorityQueue<>(NODE_ORDER);
106	
107	            for (int i = 0; i < frequencies.length; i++) {
108	                nodes.add(new Node(frequencies[i], i));
109	            }
110	
111	            return nodes;
112	        }
113	
114	        private static Node mergeLowestFrequencyNodes(PriorityQueue<Node> nodes) {
115	            Node left = nodes.poll();
116	            Node right = nodes.poll();
117	            return new Node(left, right);
118	        }
119	
120	        private static ArrayList<String> createEmptyCodeList(int size) {
121	            ArrayList<String> codes = new ArrayList<>(size);
122	
123	            for (int i = 0; i < size; i++) {
124	                codes.add("");
125	            }
126	
127	            return codes;
128	        }
129	
130	        private static void collectLeafCodes(Node root, StringBuilder prefix, BiConsumer<Node, String> consumer) {
131	            if (root == null) {
132	                return;
133	            }
134	
135	            if (root.isLeaf()) {
136	                consumer.accept(root, codeFor(prefix));
137	                return;
138	            }
139	
140	            appendBranchCode(root.left, LEFT_BRANCH_CODE, prefix, consumer);
141	            appendBranchCode(root.right, RIGHT_BRANCH_CODE, prefix, consumer);
142	        }
143	
144	        private static void appendBranchCode(Node node, char bit, StringBuilder prefix, BiConsumer<Node, String> consumer) {
145	            prefix.append(bit);
146	            collectLeafCodes(node, prefix, consumer);
147	            prefix.setLength(prefix.length() - 1);
148	        }
149	
150	        private static String codeFor(StringBuilder prefix) {
151	            return prefix.length() == 0 ? SINGLE_SYMBOL_CODE : prefix.toString();
152	        }
153	    }
154	
155	    private static void validateInput(String symbols, int[] frequencies) {
156	        Objects.requireNonNull(symbols, "Input string must not be null");
157	        Objects.requireNonNull(frequencies, "Frequency array must not be null");
158	
159	        if (symbols.length() != frequencies.length) {
160	            throw new IllegalArgumentException("Input string and frequency array must have the same length");
161	        }
162	
163	        validateFrequencies(frequencies);
164	    }
165	
166	    private static void validateFrequencies(int[] frequencies) {
167	        for (int frequency : frequencies) {
168	            if (frequency < 0) {
169	                throw new IllegalArgumentException("Frequencies must not be negative");
170	            }
171	        }
172	    }
173	}
